/*
 * Host unit test for components/nuki_uart_bridge/nuki_uart_seclink.{h,cpp}.
 *
 * Build & run:  make test-seclink
 *           or: g++ -std=c++17 -Wall -Wextra -Werror \
 *                   -Icomponents/nuki_uart_bridge \
 *                   tests/test_seclink_host.cpp \
 *                   components/nuki_uart_bridge/nuki_uart_seclink.cpp \
 *                   $(pkg-config --cflags --libs libsodium) -o t && ./t
 *
 * What is pinned here is the bridge's deterministic transcript
 * (nRF52840_nuki_bridge/tests/sec_link_vectors.txt, generated by its
 * tests/test_sec_link.c with Monocypher).  The ESP32 plays the INITIATOR:
 * from the host seeds it must produce the identical PAIR and HS_INIT bytes,
 * accept the bridge's HS_RESP, and seal / open the first DATA frame in each
 * direction byte for byte.  The RESPONDER path is exercised too so the DH
 * slot ordering is verified from both ends in one process.
 *
 * Primitive KATs come first: if they pass, libsodium agrees with RFC 7748 /
 * RFC 7693 / draft-irtf-cfrg-xchacha, and a transcript mismatch is a
 * protocol bug rather than a crypto-library one.
 *
 * Set SEC_LINK_VECTORS=/path/to/sec_link_vectors.txt to additionally check
 * that file against the pinned constants (catches a regenerated transcript).
 */

#include "nuki_uart_seclink.h"

#include <sodium.h>

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>

static int checks;
static int failures;

#define CHECK(cond)                                                            \
  do {                                                                         \
    checks++;                                                                  \
    if (!(cond)) {                                                             \
      failures++;                                                              \
      printf("FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond);                   \
    }                                                                          \
  } while (0)

static void hexdump(const char *label, const uint8_t *p, size_t n) {
  printf("%-16s", label);
  for (size_t i = 0; i < n; i++) {
    printf("%02X", p[i]);
  }
  printf("\n");
}

#define CHECK_MEM(got, exp, n)                                                 \
  do {                                                                         \
    checks++;                                                                  \
    if (memcmp((got), (exp), (n)) != 0) {                                      \
      failures++;                                                              \
      printf("FAIL %s:%d: %s != %s (%u bytes)\n", __FILE__, __LINE__, #got,    \
             #exp, (unsigned)(n));                                             \
      hexdump("  got", (got), (n));                                            \
      hexdump("  want", (exp), (n));                                           \
    }                                                                          \
  } while (0)

static int nibble(char c) {
  if (c >= '0' && c <= '9') {
    return c - '0';
  }
  if (c >= 'a' && c <= 'f') {
    return c - 'a' + 10;
  }
  if (c >= 'A' && c <= 'F') {
    return c - 'A' + 10;
  }
  return -1;
}

/* Hex -> bytes; whitespace ignored; aborts on a typo (a bad vector must not
 * pass). */
static size_t unhex(uint8_t *out, size_t out_max, const char *hex) {
  size_t n = 0;
  int hi = -1;
  for (const char *p = hex; *p != '\0'; p++) {
    if (*p == ' ' || *p == '\n' || *p == '\t' || *p == '\r') {
      continue;
    }
    int v = nibble(*p);
    if (v < 0) {
      printf("bad hex digit '%c'\n", *p);
      exit(2);
    }
    if (hi < 0) {
      hi = v;
      continue;
    }
    if (n >= out_max) {
      printf("hex too long for %u-byte buffer\n", (unsigned)out_max);
      exit(2);
    }
    out[n++] = (uint8_t)((hi << 4) | v);
    hi = -1;
  }
  if (hi >= 0) {
    printf("odd hex length\n");
    exit(2);
  }
  return n;
}

